create extension if not exists "pgcrypto";
create type public.account_role as enum ('candidate','recruiter','platform_administrator');
create type public.member_role as enum ('owner','recruiter','hiring_manager');
create type public.member_status as enum ('invited','active','inactive');
create type public.job_status as enum ('draft','published','paused','closed');
create type public.application_status as enum ('applied','screening','shortlisted','interview','offer','hired','rejected','withdrawn');
create table public.profiles (id uuid primary key references auth.users(id) on delete cascade, full_name text not null default '', email text not null, phone text, avatar_url text, account_role public.account_role not null default 'candidate', created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.organizations (id uuid primary key default gen_random_uuid(), name text not null, slug text unique not null, description text, logo_path text, website text, location text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.organization_memberships (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id) on delete cascade, user_id uuid not null references public.profiles(id) on delete cascade, role public.member_role not null, status public.member_status not null default 'invited', created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(organization_id,user_id));
create table public.candidate_profiles (user_id uuid primary key references public.profiles(id) on delete cascade, headline text, summary text, location text, skills text[] not null default '{}', years_of_experience int check(years_of_experience >= 0 and years_of_experience <= 70), education text, portfolio_url text, linkedin_url text, github_url text, resume_path text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.jobs (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id) on delete cascade, created_by uuid not null references public.profiles(id), title text not null, slug text not null, department text not null, employment_type text not null, workplace_type text not null, location text not null, description text not null, requirements text[] not null default '{}', responsibilities text[] not null default '{}', salary_min numeric, salary_max numeric, currency text default 'INR', experience_min int, experience_max int, status public.job_status not null default 'draft', published_at timestamptz, closing_at timestamptz, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(organization_id,slug), check(salary_max is null or salary_min is null or salary_max >= salary_min));
create table public.applications (id uuid primary key default gen_random_uuid(), job_id uuid not null references public.jobs(id) on delete cascade, candidate_id uuid not null references public.profiles(id) on delete cascade, resume_path text not null, cover_letter text, status public.application_status not null default 'applied', applied_at timestamptz not null default now(), updated_at timestamptz not null default now(), withdrawn_at timestamptz, unique(job_id,candidate_id));
create table public.application_events (id uuid primary key default gen_random_uuid(), application_id uuid not null references public.applications(id) on delete cascade, actor_id uuid references public.profiles(id), old_status public.application_status, new_status public.application_status, event_type text not null, description text, created_at timestamptz not null default now());
create table public.interviews (id uuid primary key default gen_random_uuid(), application_id uuid not null references public.applications(id) on delete cascade, scheduled_by uuid not null references public.profiles(id), scheduled_at timestamptz not null, duration_minutes int not null default 45 check(duration_minutes between 15 and 480), interview_type text not null, meeting_url text, location text, status text not null default 'scheduled', created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.recruiter_notes (id uuid primary key default gen_random_uuid(), application_id uuid not null references public.applications(id) on delete cascade, author_id uuid not null references public.profiles(id), content text not null check(length(content) <= 5000), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.interview_feedback (id uuid primary key default gen_random_uuid(), interview_id uuid not null references public.interviews(id) on delete cascade, author_id uuid not null references public.profiles(id), rating int check(rating between 1 and 5), feedback text, recommendation text, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(interview_id,author_id));
create table public.notifications (id uuid primary key default gen_random_uuid(), recipient_id uuid not null references public.profiles(id) on delete cascade, type text not null, title text not null, message text not null, related_application_id uuid references public.applications(id) on delete set null, read_at timestamptz, created_at timestamptz not null default now());
create table public.audit_logs (id uuid primary key default gen_random_uuid(), actor_id uuid references public.profiles(id), organization_id uuid references public.organizations(id), action text not null, entity_type text not null, entity_id uuid, metadata jsonb not null default '{}', created_at timestamptz not null default now());
create index applications_candidate_idx on public.applications(candidate_id,updated_at desc); create index applications_job_status_idx on public.applications(job_id,status); create index memberships_user_idx on public.organization_memberships(user_id,status); create index jobs_status_idx on public.jobs(status,created_at desc); create index interviews_schedule_idx on public.interviews(scheduled_at,status); create index notifications_recipient_idx on public.notifications(recipient_id,read_at,created_at desc);
alter table public.profiles enable row level security; alter table public.organizations enable row level security; alter table public.organization_memberships enable row level security; alter table public.candidate_profiles enable row level security; alter table public.jobs enable row level security; alter table public.applications enable row level security; alter table public.application_events enable row level security; alter table public.interviews enable row level security; alter table public.recruiter_notes enable row level security; alter table public.interview_feedback enable row level security; alter table public.notifications enable row level security; alter table public.audit_logs enable row level security;
create policy "public can read published jobs" on public.jobs for select using (status='published');
create policy "users read own profile" on public.profiles for select using (auth.uid()=id); create policy "users update own profile" on public.profiles for update using (auth.uid()=id);
create policy "candidates own profile" on public.candidate_profiles for all using (auth.uid()=user_id) with check(auth.uid()=user_id);
create policy "candidates own applications" on public.applications for select using (auth.uid()=candidate_id); create policy "candidates create own applications" on public.applications for insert with check(auth.uid()=candidate_id);
create policy "own notifications" on public.notifications for all using (auth.uid()=recipient_id) with check(auth.uid()=recipient_id);
-- Organization-scoped recruiter policies should be added with membership helper functions in production.
